open|ope[*_`]{0,2}n)[*_`]{0,2}[ \\\\t]*\\\\|?[ \\\\t\\\\r]*$|^[ \\\\t]*\\\\|?[ \\\\t]*[*_`]{0,2}(?:Pregnancy|Pre[*_`]{0,2}gnancy)[*_`]{0,2}[\\\\s*_`]{1,8}[*_`]{0,2}(?:Schedules|Sch[*_`]{0,2}edules)[*_`]{0,2}[ \\\\t]*\\\\|[ \\\\t]*[^|\\\\r\\\\n]*[ \\\\t]*\\\\|[ \\\\t]*[*_`]{0,2}(?:open|ope[*_`]{0,2}n)[*_`]{0,2}[ \\\\t]*\\\\|?[ \\\\t\\\\r]*$)\",\n              \"deterministic\": {\n                \"path\": \"$.text\",\n                \"comparison\": \"not_regex_match\"\n              }\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"name\": \"review_log_accounts_for_every_article_and_both_findings\",\n      \"description\": \"Splits review_log.md's 19 comment lines into the 15 open and the 4 settled the database actually holds, counts the lines carrying each Doc stage, and requires the three settled articles to appear on a settled line - the cardinality and completeness half of the per-row deliverable, so a log that drops the settled threads or fills the stage column with junk cannot score full reward.\",\n      \"category\": \"core\",\n      \"weight\": 1.0,\n      \"target\": \"workspace_files\",\n      \"verifier_type\": \"file_check\",\n      \"type\": \"file_check\",\n      \"pass_threshold\": 1.0,\n      \"requirement_id\": \"review_log_finding_coverage\",\n      \"evidence_span\": \"One line for every reviewer comment in that database,\\nwritten as `article title | Doc stage | open` while the thread that comment belongs to is still\\nwaiting on somebody, and `article title | Doc stage | settled` once that thread has been resolved.\",\n      \"metadata\": {\n        \"why_justification\": \"review_log.md is a 19-row, three-field deliverable. Before this verifier the row total was pinned at 19 and the eleven open articles were pinned to an open line, but nothing required a settled line to exist, nothing required the three settled articles to appear at all, and no assertion reached the Doc stage column. Measured through the bundle's own v