th\": \"review_log.md\"\n                }\n              }\n            },\n            \"assertion\": {\n              \"type\": \"deterministic\",\n              \"expected\": \"(?ism)\\\\A(?:(?!^[^\\\\r\\\\n]*\\\\|[ \\\\t]*[*_`]{0,2}(?:open|ope[*_`]{0,2}n)[*_`]{0,2}[ \\\\t]*\\\\|?[ \\\\t\\\\r]*$)[\\\\s\\\\S])*(?:(?:^[^\\\\r\\\\n]*\\\\|[ \\\\t]*[*_`]{0,2}(?:open|ope[*_`]{0,2}n)[*_`]{0,2}[ \\\\t]*\\\\|?[ \\\\t\\\\r]*$)(?:(?!^[^\\\\r\\\\n]*\\\\|[ \\\\t]*[*_`]{0,2}(?:open|ope[*_`]{0,2}n)[*_`]{0,2}[ \\\\t]*\\\\|?[ \\\\t\\\\r]*$)[\\\\s\\\\S])*){15}\\\\Z\",\n              \"deterministic\": {\n                \"path\": \"$.text\",\n                \"comparison\": \"regex_match\"\n              }\n            }\n          },\n          {\n            \"name\": \"review_log_has_exactly_four_settled_comment_lines\",\n            \"metadata\": {\n              \"how_justification\": \"The other half of the same split: EXACTLY 4 lines whose last pipe-separated field is settled, by the same exact-count construction and the same tolerances. 15 + 4 is the 19 the row-coverage leaf counts, so the two halves are pinned as well as the total.\",\n              \"why_justification\": \"review_log_has_one_line_per_comment pins the TOTAL at 19 and nothing splits that total by finding, so a log that never mentions a settled thread at all - 19 open lines over the eleven open articles, with Birthing Options, Nausea and Vomiting and Pregnancy Schedules absent from the file - clears every other leaf in this bundle. Measured on 2026-09-27 through this bundle's own verifier engine: that log scored 8 of 8 file_checks before this verifier existed. Splitting the count into 15 open and 4 settled is what refuses it. A run that leaves include_resolved at its default never sees a settled thread and lands on 0 here; a run that reads the resolved flag off the comment rather than the discussion lands on a different number again.\"\n            },\n            \"source\": {\n              \"type\": \"f